/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void can_dev_set_irq_rx (Can_Dev can_dev , Can_Irq_Service_Func irq_service_rx)
{
  CRITICAL ;

  if (irq_service_rx)
    {
      C_ENTER ;
        {
		  if (can_dev != NULL)
		  {
          	can_dev->irq_service_rx = irq_service_rx ;

          	can_dev->io_base [CANIER] |= 0x01 ;
		  }
        }
      C_LEAVE ;
    }
}

